<INITIAL>@includedir    {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDEDIR ");
                            return INCLUDEDIR;
