<INITIAL>^#include[[:blank:]]+.*(\r\n|\n)? {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            /* only consume #include */
                            sudoersless(sizeof("#include") - 1);
                            yy_set_bol(0);

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDE ");
                            return INCLUDE;
                        }

<INITIAL>^#includedir[[:blank:]]+.*(\r\n|\n)? {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            /* only consume #includedir */
                            sudoersless(sizeof("#includedir") - 1);
                            yy_set_bol(0);

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDEDIR ");
                            return INCLUDEDIR;
                        }

                            LEXTRACE("BEGINSTR ");
