                            parser_leak_add(LEAK_PTR, sudoerslval.string);
                            LEXTRACE("WORD(6) ");
                            return WORD;
                        }

<GOTINC>{
    [^\"[:space:]]([^[:space:]]|\\[[:blank:]])* {
                            /* include file/directory */
                            if (!fill(sudoerstext, sudoersleng))
                                yyterminate();
                            parser_leak_add(LEAK_PTR, sudoerslval.string);
                            BEGIN INITIAL;
                            LEXTRACE("WORD(7) ");
                            return WORD;
                        }

    \"                  {
                            LEXTRACE("BEGINSTR ");
                            sudoerslval.string = NULL;
                            prev_state = INITIAL;
                            BEGIN INSTR;
